    # If both orientations are available, choose the pair with the greatest span.
    candidates = []
    by_row = {}
    by_col = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
        by_col.setdefault(c, []).append(r)
    for r, cols in by_row.items():
        if len(cols) >= 2:
            candidates.append((max(cols) - min(cols), "row", r, min(cols), max(cols)))
    for c, rows in by_col.items():
        if len(rows) >= 2:
            candidates.append((max(rows) - min(rows), "col", c, min(rows), max(rows)))
    if not candidates:
        return out
    _, axis, fixed, lo, hi = max(candidates)

    if axis == "row":
        for c in range(lo, hi + 1):
            if out[fixed][c] == 0:
                out[fixed][c] = 3
        for r, c in points:
            if r == fixed:
                continue
            for rr in range(min(r, fixed) + 1, max(r, fixed)):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        for r in range(lo, hi + 1):
            if out[r][fixed] == 0:
                out[r][fixed] = 3
        for r, c in points:
